import{_ as n,o as t,c as e,a6 as s}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"ImGui Integration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/imgui-integration.md","filePath":"guide/imgui-integration.md","lastUpdated":1781686130000}'),i={name:"guide/imgui-integration.md"};function l(d,a,o,r,p,c){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="imgui-integration" tabindex="-1">ImGui Integration <a class="header-anchor" href="#imgui-integration" aria-label="Permalink to “ImGui Integration”">​</a></h1><p>NG integrates with <a href="https://github.com/ocornut/imgui" target="_blank" rel="noreferrer">Dear ImGui</a> for immediate-mode GUI programming. This enables creating interactive graphical applications directly in NG.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The ImGui binding provides:</p><ul><li>Window and widget creation</li><li>Mouse and keyboard input handling</li><li>Drawing primitives</li><li>Integration with SDL3 for window management</li></ul><h2 id="running-imgui-examples" tabindex="-1">Running ImGui Examples <a class="header-anchor" href="#running-imgui-examples" aria-label="Permalink to “Running ImGui Examples”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the demo application</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the NG ImGui example</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/imgui_example.ng</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the NG IDE demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/ng_ide.ng</span></span></code></pre></div><h2 id="basic-example" tabindex="-1">Basic Example <a class="header-anchor" href="#basic-example" aria-label="Permalink to “Basic Example”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.imgui;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ImGuiExample.ng</span></span>
<span class="line"><span>fun main() {</span></span>
<span class="line"><span>    val show_demo_window = true;</span></span>
<span class="line"><span>    val show_another_window = false;</span></span>
<span class="line"><span>    val clear_color = (0.45f32, 0.55f32, 0.60f32, 1.00f32);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Create and run the ImGui application loop</span></span>
<span class="line"><span>    runImGui(&quot;NG ImGui Example&quot;, {</span></span>
<span class="line"><span>        // Main menu bar</span></span>
<span class="line"><span>        if (beginMenuBar()) {</span></span>
<span class="line"><span>            if (beginMenu(&quot;File&quot;)) {</span></span>
<span class="line"><span>                if (menuItem(&quot;Exit&quot;)) {</span></span>
<span class="line"><span>                    closeImGui();</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                endMenu();</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            endMenuBar();</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Demo window</span></span>
<span class="line"><span>        showDemoWindow(ref show_demo_window);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Custom window</span></span>
<span class="line"><span>        if (begin(&quot;Hello, NG!&quot;)) {</span></span>
<span class="line"><span>            text(&quot;This is an ImGui window from NG!&quot;);</span></span>
<span class="line"><span>            text(&quot;Counter:&quot;);</span></span>
<span class="line"><span>            sameLine();</span></span>
<span class="line"><span>            button(&quot;Click me&quot;);</span></span>
<span class="line"><span>            end();</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    });</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="available-functions" tabindex="-1">Available Functions <a class="header-anchor" href="#available-functions" aria-label="Permalink to “Available Functions”">​</a></h2><p>The <code>std.imgui</code> module exposes a comprehensive subset of ImGui&#39;s API:</p><h3 id="window-management" tabindex="-1">Window Management <a class="header-anchor" href="#window-management" aria-label="Permalink to “Window Management”">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>begin(name: string, p_open: ref&lt;bool&gt;) -&gt; bool</code></td><td>Start a window</td></tr><tr><td><code>end()</code></td><td>End a window</td></tr><tr><td><code>beginChild(id: string) -&gt; bool</code></td><td>Start a child window</td></tr><tr><td><code>endChild()</code></td><td>End a child window</td></tr><tr><td><code>setNextWindowSize(size: (f32, f32))</code></td><td>Set next window size</td></tr><tr><td><code>setNextWindowPos(pos: (f32, f32))</code></td><td>Set next window position</td></tr></tbody></table><h3 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to “Widgets”">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>text(fmt: string)</code></td><td>Display text</td></tr><tr><td><code>button(label: string) -&gt; bool</code></td><td>Clickable button</td></tr><tr><td><code>checkbox(label: string, v: ref&lt;bool&gt;) -&gt; bool</code></td><td>Checkbox</td></tr><tr><td><code>sliderFloat(label: string, v: ref&lt;f32&gt;, min: f32, max: f32) -&gt; bool</code></td><td>Float slider</td></tr><tr><td><code>sliderInt(label: string, v: ref&lt;i32&gt;, min: i32, max: i32) -&gt; bool</code></td><td>Int slider</td></tr><tr><td><code>inputText(label: string, buf: ref&lt;string&gt;) -&gt; bool</code></td><td>Text input</td></tr><tr><td><code>combo(label: string, current: ref&lt;i32&gt;, items: [string]) -&gt; bool</code></td><td>Combo box</td></tr><tr><td><code>colorEdit3(label: string, col: ref&lt;(f32, f32, f32)&gt;) -&gt; bool</code></td><td>Color picker</td></tr></tbody></table><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>sameLine()</code></td><td>Place next widget on same line</td></tr><tr><td><code>spacing()</code></td><td>Add spacing</td></tr><tr><td><code>separator()</code></td><td>Add separator line</td></tr><tr><td><code>indent()</code></td><td>Indent widgets</td></tr><tr><td><code>unindent()</code></td><td>Unindent widgets</td></tr><tr><td><code>group()</code></td><td>Group widgets</td></tr><tr><td><code>dummy(size: (f32, f32))</code></td><td>Add dummy space</td></tr></tbody></table><h3 id="menus" tabindex="-1">Menus <a class="header-anchor" href="#menus" aria-label="Permalink to “Menus”">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>beginMenuBar() -&gt; bool</code></td><td>Start menu bar</td></tr><tr><td><code>endMenuBar()</code></td><td>End menu bar</td></tr><tr><td><code>beginMenu(label: string) -&gt; bool</code></td><td>Start menu</td></tr><tr><td><code>endMenu()</code></td><td>End menu</td></tr><tr><td><code>menuItem(label: string) -&gt; bool</code></td><td>Menu item</td></tr></tbody></table><h3 id="drawing" tabindex="-1">Drawing <a class="header-anchor" href="#drawing" aria-label="Permalink to “Drawing”">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>drawLine(p1: (f32, f32), p2: (f32, f32), col: u32)</code></td><td>Draw a line</td></tr><tr><td><code>drawRect(p1: (f32, f32), p2: (f32, f32), col: u32)</code></td><td>Draw a rectangle outline</td></tr><tr><td><code>drawRectFilled(p1: (f32, f32), p2: (f32, f32), col: u32)</code></td><td>Draw a filled rectangle</td></tr><tr><td><code>drawCircle(center: (f32, f32), radius: f32, col: u32)</code></td><td>Draw a circle</td></tr><tr><td><code>drawText(pos: (f32, f32), text: string, col: u32)</code></td><td>Draw text</td></tr></tbody></table><h3 id="application-control" tabindex="-1">Application Control <a class="header-anchor" href="#application-control" aria-label="Permalink to “Application Control”">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>runImGui(title: string, frame_fn: () -&gt; unit)</code></td><td>Run the main loop</td></tr><tr><td><code>closeImGui()</code></td><td>Request application exit</td></tr><tr><td><code>showDemoWindow(p_open: ref&lt;bool&gt;)</code></td><td>Show ImGui demo window</td></tr></tbody></table><h2 id="complete-example-color-picker" tabindex="-1">Complete Example: Color Picker <a class="header-anchor" href="#complete-example-color-picker" aria-label="Permalink to “Complete Example: Color Picker”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.imgui;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun main() {</span></span>
<span class="line"><span>    val bg_color = (0.1f32, 0.2f32, 0.3f32, 1.0f32);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    runImGui(&quot;Color Picker&quot;, {</span></span>
<span class="line"><span>        if (begin(&quot;Settings&quot;)) {</span></span>
<span class="line"><span>            text(&quot;Background Color:&quot;);</span></span>
<span class="line"><span>            colorEdit3(&quot;Color&quot;, ref bg_color);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            if (button(&quot;Reset&quot;)) {</span></span>
<span class="line"><span>                bg_color = (0.1f32, 0.2f32, 0.3f32, 1.0f32);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            end();</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Use bg_color for clear color</span></span>
<span class="line"><span>        setClearColor(bg_color.0, bg_color.1, bg_color.2, bg_color.3);</span></span>
<span class="line"><span>    });</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="the-ng-ide" tabindex="-1">The NG IDE <a class="header-anchor" href="#the-ng-ide" aria-label="Permalink to “The NG IDE”">​</a></h2><p>The repository includes a full NG IDE built with ImGui (<code>example/ng_ide.ng</code>):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/ng_ide.ng</span></span></code></pre></div><p>This demonstrates:</p><ul><li>Code editing with syntax highlighting</li><li>File loading and saving</li><li>Integrated NG execution</li><li>Multiple dockable windows</li></ul><h2 id="imgui-demo-application" tabindex="-1">ImGui Demo Application <a class="header-anchor" href="#imgui-demo-application" aria-label="Permalink to “ImGui Demo Application”">​</a></h2><p>There&#39;s also a standalone C++ test application:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ng_imgui_demo</span></span></code></pre></div><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p>The ImGui integration works through:</p><ol><li><strong>NG types and functions</strong> declared in <code>lib/std/imgui.ng</code></li><li><strong>Native C++ implementations</strong> in <code>src/stdlib/imgui.cpp</code></li><li><strong>SDL3</strong> for window and input management</li><li><strong>ImGui</strong> for immediate-mode GUI rendering</li></ol><p>The VM bridges NG function calls to C++ implementations transparently.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Review the <a href="https://github.com/ng-lang/ng/tree/main/example" target="_blank" rel="noreferrer">example programs</a> for a complete list of runnable programs, or check the <a href="./language_guide">Language Guide</a> for other topics.</p><blockquote><p><strong>Try it:</strong> <code>example/imgui_example.ng</code> — ImGui basics <strong>Try it:</strong> <code>example/ng_ide.ng</code> — Full NG IDE</p></blockquote>`,40)])])}const u=n(i,[["render",l]]);export{g as __pageData,u as default};
